/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var isWebAssemblyMemory = require( '@stdlib/assert/is-wasm-memory' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var inherits = require( '@stdlib/utils/inherit' );
var WasmModule = require( '@stdlib/wasm/module-wrapper' );
var format = require( '@stdlib/string/format' );
var wasmBinary = require( '@stdlib/stats/strided/wasm/dmeanvar/lib/binary.js' );


// MAIN //

/**
* WebAssembly module wrapper constructor.
*
* @constructor
* @param {Object} memory - WebAssembly memory instance
* @throws {TypeError} must provide a WebAssembly memory instance
* @returns {Module} module instance
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var mod = new dmeanvar.Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* mod.initializeSync();
*
* // Define a vector data type:
* var dtype = 'float64';
*
* // Specify a vector length:
* var N = 3;
*
* // Define a pointer (i.e., byte offset) to the first vector element:
* var xptr = 0;
*
* // Allocate space for the output:
* var out = new Float64Array( 2 );
*
* // Write vector values to module memory:
* mod.write( xptr, oneTo( N, dtype ) );
*
* // Perform computation:
* var y = mod.main( N, 1, xptr, 1, out, 1 );
* // returns <Float64Array>[ 2.0, 1.0 ]
*/
function Module( memory ) {
	if ( !( this instanceof Module ) ) {
		return new Module( memory );
	}
	if ( !isWebAssemblyMemory( memory ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a WebAssembly memory instance. Value: `%s`.', memory ) );
	}
	// Call the parent constructor:
	WasmModule.call( this, wasmBinary, memory, {
		'env': {
			'memory': memory
		}
	});

	return this;
}

// Inherit from the parent constructor:
inherits( Module, WasmModule );

/**
* Computes the mean and variance of a double-precision floating-point strided array.
*
* @name main
* @memberof Module.prototype
* @readonly
* @type {Function}
* @param {PositiveInteger} N - number of indexed elements
* @param {PositiveInteger} correction - degrees of freedom adjustment
* @param {integer} xptr - input array pointer (i.e., byte offset)
* @param {integer} strideX - stride length
* @param {Float64Array} out - output array
* @param {integer} strideOut - `out` stride length
* @returns {Float64Array} output array
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var mod = new dmeanvar.Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* mod.initializeSync();
*
* // Define a vector data type:
* var dtype = 'float64';
*
* // Specify a vector length:
* var N = 3;
*
* // Define a pointer (i.e., byte offset) to the first vector element:
* var xptr = 0;
*
* // Allocate space for the output:
* var out = new Float64Array( 2 );
*
* // Write vector values to module memory:
* mod.write( xptr, oneTo( N, dtype ) );
*
* // Perform computation:
* var y = mod.main( N, 1, xptr, 1, out, 1 );
* // returns <Float64Array>[ 2.0, 1.0 ]
*/
setReadOnly( Module.prototype, 'main', function dmeanvar( N, correction, xptr, strideX, out, strideOut ) {
	return this._instance.exports.stdlib_strided_dmeanvar( N, correction, xptr, strideX, out, strideOut );
});

/**
* Computes the arithmetic mean of a double-precision floating-point strided array using Welford's algorithm and alternative indexing semantics.
*
* @name ndarray
* @memberof Module.prototype
* @readonly
* @type {Function}
* @param {PositiveNumber} N - number of indexed elements
* @param {PositiveNumber} correction - degrees of freedom adjustment
* @param {integer} xptr - input array pointer (i.e., byte offset)
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @param {Float64Array} out - output array
* @param {integer} strideOut - `out` stride length
* @param {NonNegativeInteger} offsetOut - `out` starting index
* @returns {Float64Array} output array
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var mod = new dmeanvar.Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* mod.initializeSync();
*
* // Define a vector data type:
* var dtype = 'float64';
*
* // Specify a vector length:
* var N = 3;
*
* // Define a pointer (i.e., byte offset) to the first vector element:
* var xptr = 0;
*
* // Allocate space for the output:
* var out = new Float64Array( 2 );
*
* // Write vector values to module memory:
* mod.write( xptr, oneTo( N, dtype ) );
*
* // Perform computation:
* var y = mod.ndarray( N, 1, xptr, 1, 0, out, 1, 0 );
* // returns <Float64Array>[ 2.0, 1.0 ]
*/
setReadOnly( Module.prototype, 'ndarray', function dmeanvar( N, correction, xptr, strideX, offsetX, out, strideOut, offsetOut ) {
	return this._instance.exports.stdlib_strided_dmeanvar_ndarray( N, correction, xptr, strideX, offsetX, out, strideOut, offsetOut ); // eslint-disable-line max-len
});


// EXPORTS //

module.exports = Module;
